with filtered as (select id, account_id, amount, txn_time, merchant, is_flagged, concat_ws('-', merchant, txn_type) as merchant_txn_type_key, coalesce(merchant, 'UNKNOWN') as merchant_clean from transactions where merchant is not null and merchant is distinct from 'Shell'), with_prev as (select *, lag(txn_time) over (partition by merchant order by txn_time, id) as prev_txn_time from filtered), gaps as (select *, case when prev_txn_time is null or txn_time > prev_txn_time + interval '14' day then 1 else 0 end as new_group_flag from with_prev), islands as (select id, amount, txn_time, merchant, is_flagged, merchant_txn_type_key, merchant_clean, sum(new_group_flag) over (partition by merchant order by txn_time, id rows between unbounded preceding and current row) as island_id from gaps) select merchant, min(island_id) as min_island_id, count(*) as row_count from islands group by 1;
